package net.civeira.phylax.feature.identity.tenanttermsofuse.application.usecase.update;

import java.time.LocalDateTime;
import java.time.ZoneId;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.access.resourceserver.domain.ResourceServerReference;
import net.civeira.phylax.feature.identity.tenant.domain.TenantReference;
import net.civeira.phylax.feature.identity.tenanttermsofuse.domain.TenantTermsOfUseChangeSet;

class TenantTermsOfUseUpdateInputUnitTest {

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the tenant terms of use input values are kept when converted to a change set and back")
  void test_tenant_terms_of_use_update_input_change_set_round_trip() {
    TenantTermsOfUseUpdateInput input = TenantTermsOfUseUpdateInput.builder().uid("one")
        .tenant(TenantReference.of("one")).resourceServer(ResourceServerReference.of("one"))
        .text("one").enabled(true).document("file_1").activationDate(LocalDateTime
            .of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime())
        .version(1).build();
    TenantTermsOfUseChangeSet changes = input.toChangeSet();
    Assertions.assertNotNull(changes, "A change set must be created");
    TenantTermsOfUseUpdateInput copy = TenantTermsOfUseUpdateInput.fromChangeSet(changes);
    Assertions.assertTrue(input.getUid().isPresent(), "uid must be assigned by the builder");
    Assertions.assertEquals(input.getUid(), copy.getUid(),
        "uid must survive the change set round trip");
    Assertions.assertTrue(input.getTenant().isPresent(), "tenant must be assigned by the builder");
    Assertions.assertEquals(input.getTenant(), copy.getTenant(),
        "tenant must survive the change set round trip");
    Assertions.assertTrue(input.getResourceServer().isPresent(),
        "resourceServer must be assigned by the builder");
    Assertions.assertEquals(input.getResourceServer(), copy.getResourceServer(),
        "resourceServer must survive the change set round trip");
    Assertions.assertTrue(input.getText().isPresent(), "text must be assigned by the builder");
    Assertions.assertEquals(input.getText(), copy.getText(),
        "text must survive the change set round trip");
    Assertions.assertTrue(input.getEnabled().isPresent(),
        "enabled must be assigned by the builder");
    Assertions.assertEquals(input.getEnabled(), copy.getEnabled(),
        "enabled must survive the change set round trip");
    Assertions.assertTrue(input.getDocument().isPresent(),
        "document must be assigned by the builder");
    Assertions.assertEquals(input.getDocument(), copy.getDocument(),
        "document must survive the change set round trip");
    Assertions.assertTrue(input.getActivationDate().isPresent(),
        "activationDate must be assigned by the builder");
    Assertions.assertEquals(input.getActivationDate(), copy.getActivationDate(),
        "activationDate must survive the change set round trip");
    Assertions.assertTrue(input.getVersion().isPresent(),
        "version must be assigned by the builder");
    Assertions.assertEquals(input.getVersion(), copy.getVersion(),
        "version must survive the change set round trip");
  }

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the tenant terms of use input builder can generate a new identifier")
  void test_tenant_terms_of_use_update_input_new_uid() {
    TenantTermsOfUseUpdateInput input = TenantTermsOfUseUpdateInput.builder().newUid().build();
    Assertions.assertTrue(input.getUid().isPresent(), "A new uid must be generated");
    Assertions.assertTrue(input.getVersion().isPresent(), "The initial version must be assigned");
    Assertions.assertNotEquals(input.getUid(),
        TenantTermsOfUseUpdateInput.builder().newUid().build().getUid(),
        "Each new uid must be different");
  }

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the tenant terms of use input starts empty and the setters assign values")
  void test_tenant_terms_of_use_update_input_setters() {
    TenantTermsOfUseUpdateInput empty = TenantTermsOfUseUpdateInput.builder().build();
    Assertions.assertTrue(empty.getUid().isEmpty(), "uid must be empty by default");
    Assertions.assertSame(empty, empty.setUid("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUid().isPresent(), "uid must be assigned by the setter");
    Assertions.assertTrue(empty.getTenant().isEmpty(), "tenant must be empty by default");
    Assertions.assertSame(empty, empty.setTenant(TenantReference.of("one")),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getTenant().isPresent(), "tenant must be assigned by the setter");
    Assertions.assertTrue(empty.getResourceServer().isEmpty(),
        "resourceServer must be empty by default");
    Assertions.assertSame(empty, empty.setResourceServer(ResourceServerReference.of("one")),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getResourceServer().isPresent(),
        "resourceServer must be assigned by the setter");
    Assertions.assertTrue(empty.getText().isEmpty(), "text must be empty by default");
    Assertions.assertSame(empty, empty.setText("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getText().isPresent(), "text must be assigned by the setter");
    Assertions.assertTrue(empty.getEnabled().isEmpty(), "enabled must be empty by default");
    Assertions.assertSame(empty, empty.setEnabled(true), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getEnabled().isPresent(), "enabled must be assigned by the setter");
    Assertions.assertTrue(empty.getDocument().isEmpty(), "document must be empty by default");
    Assertions.assertSame(empty, empty.setDocument("file_1"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getDocument().isPresent(),
        "document must be assigned by the setter");
    Assertions.assertTrue(empty.getActivationDate().isEmpty(),
        "activationDate must be empty by default");
    Assertions.assertSame(empty,
        empty.setActivationDate(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime()),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getActivationDate().isPresent(),
        "activationDate must be assigned by the setter");
    Assertions.assertTrue(empty.getVersion().isEmpty(), "version must be empty by default");
    Assertions.assertSame(empty, empty.setVersion(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getVersion().isPresent(), "version must be assigned by the setter");
    Assertions.assertNotNull(empty.toChangeSet(), "A change set must be created");
  }
}
